package com.example.madfinalproject;
import android.content.Intent; import android.os.Bundle; import android.widget.TextView; import android.widget.Toast; import androidx.appcompat.app.AppCompatActivity;
public class PteMockTestsActivity extends AppCompatActivity {protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_ielts_mock_tests);PteUiAdapter.apply(findViewById(android.R.id.content));((TextView)findViewById(R.id.tabMockTests)).setTextColor(PteUiAdapter.TEAL);wire();findViewById(R.id.btnStartMock).setOnClickListener(v->Toast.makeText(this,"Starting new PTE mock test",Toast.LENGTH_SHORT).show());}private void wire(){findViewById(R.id.btnBack).setOnClickListener(v->finish());findViewById(R.id.tabOverview).setOnClickListener(v->open(PtePreparationActivity.class));findViewById(R.id.tabLessons).setOnClickListener(v->open(PteLessonsActivity.class));findViewById(R.id.tabPractice).setOnClickListener(v->open(PtePracticeActivity.class));findViewById(R.id.tabReports).setOnClickListener(v->open(PteReportsActivity.class));}private void open(Class<?> c){startActivity(new Intent(this,c));finish();}}
